set difficulty = case
  when id in (
    '00000042-0000-4000-8000-000000000019','00000042-0000-4000-8000-000000000020','00000042-0000-4000-8000-000000000021','00000042-0000-4000-8000-000000000022','00000042-0000-4000-8000-000000000023','00000042-0000-4000-8000-000000000024','00000042-0000-4000-8000-000000000025',
