where subject_id = '20000000-0000-4000-8000-000000000004'
  and publication_status = 'published'
  and id between '00000042-0000-4000-8000-000000000019' and '00000042-0000-4000-8000-000000000100';

-- Lote de aplicações: vértice é direto; extremos em intervalo e leitura de
-- gráfico exigem interpretação; testes de sinal completos são difíceis.
update public.questions
set difficulty = case
  when id between '00000043-0000-4000-8000-000000015100' and '00000043-0000-4000-8000-000000015107'
    then 'easy'::public.question_difficulty
  when id between '00000043-0000-4000-8000-000000015116' and '00000043-0000-4000-8000-000000015122'
    then 'hard'::public.question_difficulty
  when id in ('00000043-0000-4000-8000-000000015124','00000043-0000-4000-8000-000000015129','00000043-0000-4000-8000-000000015134','00000043-0000-4000-8000-000000015139')
    then 'easy'::public.question_difficulty
  else 'medium'::public.question_difficulty
end
where subject_id = '20000000-0000-4000-8000-000000000004'
  and publication_status = 'published'
  and id between '00000043-0000-4000-8000-000000015100' and '00000043-0000-4000-8000-000000015142';

commit;
